-- =============================================
-- Author:		Richard Mays
-- Create date: 7/21/2016
-- Description:	Fills the REG_PAGE_SETTING
-- =============================================
CREATE PROCEDURE [dbo].[DCConv_LkUp_PopulateREG_PAGE_SETTING] 
	@pin_run_reference_time datetime
AS
BEGIN
 -- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

	DECLARE @MMIS_PROVIDER_TYPE_ID varchar(5);

	DELETE FROM [dbo].[REG_PAGE_SETTING];

	DBCC CHECKIDENT('dbo.REG_PAGE_SETTING', RESEED, 0);
	

	
	-- Additional inserts and updates
	-- Waiver Services
	SELECT PROVIDER_CATEGORY_TYPE_ID as ENTITY_TYPE_ID, PROVIDER_TYPE_ID, 'Waiver Services', '',0 ,0 , '2016-07-20 00:00:00.000' ,
	 '5D0689A8-D885-4211-B9FD-56757474AB4D', NULL, 1, APPLICATION_TYPE_ID
	FROM PROVIDER_TYPE 
	WHERE  MMIS_PROVIDER_TYPE_ID NOT IN ('W04', 'W01', 'W02')
	UNION
	SELECT PROVIDER_CATEGORY_TYPE_ID as ENTITY_TYPE_ID, PROVIDER_TYPE_ID, 'Waiver Services', '',1 ,1 , '2016-07-20 00:00:00.000' ,
	 '5D0689A8-D885-4211-B9FD-56757474AB4D', NULL, 1, APPLICATION_TYPE_ID
	FROM PROVIDER_TYPE 
	WHERE  MMIS_PROVIDER_TYPE_ID IN ('W04', 'W01', 'W02')

	-- ACH Authorization
	SELECT PROVIDER_CATEGORY_TYPE_ID as ENTITY_TYPE_ID, PROVIDER_TYPE_ID, 'ACHAuthorization', '',0 ,0 , '2016-07-20 00:00:00.000' ,
	 '5D0689A8-D885-4211-B9FD-56757474AB4D', NULL, 1, APPLICATION_TYPE_ID
	FROM PROVIDER_TYPE 

	-- Application Fee
	SELECT PROVIDER_CATEGORY_TYPE_ID as ENTITY_TYPE_ID, PROVIDER_TYPE_ID, 'Application Fee', '',0 ,0 , '2016-07-20 00:00:00.000' ,
	 '5D0689A8-D885-4211-B9FD-56757474AB4D', NULL, 1, APPLICATION_TYPE_ID
	FROM PROVIDER_TYPE 
	WHERE  MMIS_PROVIDER_TYPE_ID IN ('A00', 'A01', 'A02', 'A04', 'A05', 'C00','D05','G00', 'H02', 'H03', 'K00', 'K01', 'K02', 'M00', 'M01', 'N00', 'N01', 'P00', 'P01', 'P02', 'R01', 'R02', 'S00', 'S01', 'T01', 'U00', 'U09', 'U10', 'V01', 'W01', 'W02', 'W04', 'X00', 'X01', 'X02', 'X03', 'X04', 'X06', 'Z00', 'Z01', 'Z02')
	UNION 
	SELECT PROVIDER_CATEGORY_TYPE_ID as ENTITY_TYPE_ID, PROVIDER_TYPE_ID, 'Application Fee', '',1 ,1 , '2016-07-20 00:00:00.000' ,
	 '5D0689A8-D885-4211-B9FD-56757474AB4D', NULL, 1, APPLICATION_TYPE_ID
	FROM PROVIDER_TYPE 
	WHERE  MMIS_PROVIDER_TYPE_ID IN ('B00','B01', 'D00', 'D01', 'D02', 'D03', 'D04','E00' , 'F00','H00','H01', 'I00', 'J00', 'J01', 'J02', 'L00', 'L01', 'Q01', 'Q02', 'T00', 'V00', 'X05' )



	-- Agreements
	DELETE FROM REG_PAGE_SETTING WHERE REG_PAGE_NAME = 'Agreements' and REG_PAGE_SECTION = 'Agreements';

	SELECT PROVIDER_CATEGORY_TYPE_ID as ENTITY_TYPE_ID, PROVIDER_TYPE_ID, 'Agreements', 'Agreements', 1 ,1 , '2016-07-20 00:00:00.000' , '5D0689A8-D885-4211-B9FD-56757474AB4D', 
	NULL, 1, APPLICATION_TYPE_ID
	FROM PROVIDER_TYPE WHERE  MMIS_PROVIDER_TYPE_ID NOT IN ('I00')
	UNION
	SELECT PROVIDER_CATEGORY_TYPE_ID as ENTITY_TYPE_ID, PROVIDER_TYPE_ID, 'Agreements', 'Agreements',0 ,0 , '2016-07-20 00:00:00.000' , '5D0689A8-D885-4211-B9FD-56757474AB4D', 
	NULL, 1, APPLICATION_TYPE_ID
	FROM PROVIDER_TYPE WHERE  MMIS_PROVIDER_TYPE_ID IN ('I00')

	IF EXISTS (SELECT REG_PAGE_SETTING_ID FROM REG_PAGE_SETTING WHERE IS_VISIBLE = 0 AND REG_PAGE_NAME = 'Agreements' AND REG_PAGE_SECTION = 'Agreements' AND PROVIDER_TYPE_ID IN (SELECT PROVIDER_TYPE_ID FROM PROVIDER_TYPE WHERE MMIS_PROVIDER_TYPE_ID = 'X06'))
	BEGIN
		UPDATE REG_PAGE_SETTING SET IS_VISIBLE = 1, IS_EDITABLE = 1
		WHERE REG_PAGE_NAME = 'Agreements' 
		AND REG_PAGE_SECTION = 'Agreements'
		AND PROVIDER_TYPE_ID IN (SELECT PROVIDER_TYPE_ID FROM PROVIDER_TYPE WHERE MMIS_PROVIDER_TYPE_ID = 'X06')
	END

	IF EXISTS (SELECT REG_PAGE_SETTING_ID FROM REG_PAGE_SETTING WHERE IS_VISIBLE = 0 AND REG_PAGE_NAME = 'Agreements' AND REG_PAGE_SECTION = 'AuthorizationReleaseInformation' AND PROVIDER_TYPE_ID IN (SELECT PROVIDER_TYPE_ID FROM PROVIDER_TYPE WHERE MMIS_PROVIDER_TYPE_ID = 'X06'))
	BEGIN
		UPDATE REG_PAGE_SETTING SET IS_VISIBLE = 1, IS_EDITABLE = 1
		WHERE REG_PAGE_NAME = 'Agreements' 
		AND REG_PAGE_SECTION = 'AuthorizationReleaseInformation'
		AND PROVIDER_TYPE_ID IN (SELECT PROVIDER_TYPE_ID FROM PROVIDER_TYPE WHERE MMIS_PROVIDER_TYPE_ID = 'X06')
	END

	IF EXISTS (SELECT REG_PAGE_SETTING_ID FROM REG_PAGE_SETTING WHERE IS_VISIBLE = 0 AND REG_PAGE_NAME = 'Agreements' AND REG_PAGE_SECTION = 'MalpracticeClaimsHistory' AND PROVIDER_TYPE_ID IN (SELECT PROVIDER_TYPE_ID FROM PROVIDER_TYPE WHERE MMIS_PROVIDER_TYPE_ID = 'X06'))
	BEGIN
		UPDATE REG_PAGE_SETTING SET IS_VISIBLE = 1, IS_EDITABLE = 1
		WHERE REG_PAGE_NAME = 'Agreements' 
		AND REG_PAGE_SECTION = 'MalpracticeClaimsHistory'
		AND PROVIDER_TYPE_ID IN (SELECT PROVIDER_TYPE_ID FROM PROVIDER_TYPE WHERE MMIS_PROVIDER_TYPE_ID = 'X06')
	END


	-- Certfication
	IF NOT EXISTS (SELECT REG_PAGE_SETTING_ID FROM REG_PAGE_SETTING WHERE ENTITY_TYPE_ID = 0 AND PROVIDER_TYPE_ID = 0 AND REG_PAGE_NAME = 'Certification' AND APPLICATION_TYPE_ID = 2)
	BEGIN
		VALUES (0, 0, 'Certification', '', 0, 0, getdate(), '5D0689A8-D885-4211-B9FD-56757474AB4D', '', 1, 2)
	END

	IF NOT EXISTS (SELECT REG_PAGE_SETTING_ID FROM REG_PAGE_SETTING WHERE ENTITY_TYPE_ID = 0 AND PROVIDER_TYPE_ID = 0 AND REG_PAGE_NAME = 'Certification' AND APPLICATION_TYPE_ID = 1)
	BEGIN
		VALUES (0, 0, 'Certification', '', 0, 0, getdate(), '5D0689A8-D885-4211-B9FD-56757474AB4D', '', 1, 1)
	END

	IF NOT EXISTS (SELECT REG_PAGE_SETTING_ID FROM REG_PAGE_SETTING WHERE ENTITY_TYPE_ID = 0 AND PROVIDER_TYPE_ID = 0 AND REG_PAGE_NAME = 'Certification' AND APPLICATION_TYPE_ID = 3)
	BEGIN
		VALUES (0, 0, 'Certification', '', 0, 0, getdate(), '5D0689A8-D885-4211-B9FD-56757474AB4D', '', 1, 3)
	END

	IF NOT EXISTS (SELECT REG_PAGE_SETTING_ID FROM REG_PAGE_SETTING WHERE ENTITY_TYPE_ID = 0 AND PROVIDER_TYPE_ID = 0 AND REG_PAGE_NAME = 'Certification' AND APPLICATION_TYPE_ID = 4)
	BEGIN
		VALUES (0, 0, 'Certification', '', 0, 0, getdate(), '5D0689A8-D885-4211-B9FD-56757474AB4D', '', 1, 4)
	END

	IF NOT EXISTS (SELECT REG_PAGE_SETTING_ID FROM REG_PAGE_SETTING WHERE ENTITY_TYPE_ID = 0 AND PROVIDER_TYPE_ID = 0 AND REG_PAGE_NAME = 'Certification' AND APPLICATION_TYPE_ID = 5)
	BEGIN
		VALUES (0, 0, 'Certification', '', 0, 0, getdate(), '5D0689A8-D885-4211-B9FD-56757474AB4D', '', 1, 5)
	END

	IF NOT EXISTS (SELECT REG_PAGE_SETTING_ID FROM REG_PAGE_SETTING WHERE ENTITY_TYPE_ID = 0 AND PROVIDER_TYPE_ID = 0 AND REG_PAGE_NAME = 'Certification' AND APPLICATION_TYPE_ID = 6)
	BEGIN
		VALUES (0, 0, 'Certification', '', 0, 0, getdate(), '5D0689A8-D885-4211-B9FD-56757474AB4D', '', 1, 6)
	END

	IF NOT EXISTS (SELECT REG_PAGE_SETTING_ID FROM REG_PAGE_SETTING WHERE ENTITY_TYPE_ID = 0 AND PROVIDER_TYPE_ID = 0 AND REG_PAGE_NAME = 'Certification' AND APPLICATION_TYPE_ID = 7)
	BEGIN
		VALUES (0, 0, 'Certification', '', 0, 0, getdate(), '5D0689A8-D885-4211-B9FD-56757474AB4D', '', 1, 7)
	END

	-- Substitute W9
	UPDATE [dbo].[REG_PAGE_SETTING] 
	SET REG_PAGE_NAME = 'Substitute W9 Form'
	WHERE REG_PAGE_NAME = 'Substitute W9' AND REG_PAGE_SECTION = '';

	SELECT PROVIDER_CATEGORY_TYPE_ID, PROVIDER_TYPE_ID, 'Substitute W9', 'ProfitStatus',0 ,0 , '2016-07-20 00:00:00.000' , '5D0689A8-D885-4211-B9FD-56757474AB4D', 
	NULL, 1, APPLICATION_TYPE_ID
	FROM PROVIDER_TYPE 
	UNION
	SELECT PROVIDER_CATEGORY_TYPE_ID, PROVIDER_TYPE_ID, 'Substitute W9', 'W9Address',0 ,0 , '2016-07-20 00:00:00.000' , '5D0689A8-D885-4211-B9FD-56757474AB4D', 
	'Provider Data Entry', 1, APPLICATION_TYPE_ID
	FROM PROVIDER_TYPE --WHERE  MMIS_PROVIDER_TYPE_ID NOT IN ('W04', 'W01', 'W02')
	UNION
	SELECT PROVIDER_CATEGORY_TYPE_ID, PROVIDER_TYPE_ID, 'Substitute W9', 'W9Address',1 ,1 , '2016-07-20 00:00:00.000' , '5D0689A8-D885-4211-B9FD-56757474AB4D', 
	'Provider Review', 1, APPLICATION_TYPE_ID
	FROM PROVIDER_TYPE --WHERE  MMIS_PROVIDER_TYPE_ID IN ('W04', 'W01', 'W02')
	UNION
	SELECT PROVIDER_CATEGORY_TYPE_ID, PROVIDER_TYPE_ID, 'Substitute W9', 'PracticeType',0 ,0 , '2016-07-20 00:00:00.000' , '5D0689A8-D885-4211-B9FD-56757474AB4D', 
	'Provider Data Entry', 1, APPLICATION_TYPE_ID
	FROM PROVIDER_TYPE --WHERE  MMIS_PROVIDER_TYPE_ID NOT IN ('W04', 'W01', 'W02')
	UNION
	SELECT PROVIDER_CATEGORY_TYPE_ID, PROVIDER_TYPE_ID, 'Substitute W9', 'PracticeType',1 ,1 , '2016-07-20 00:00:00.000' , '5D0689A8-D885-4211-B9FD-56757474AB4D', 
	'Provider Review', 1, APPLICATION_TYPE_ID
	FROM PROVIDER_TYPE --WHERE  MMIS_PROVIDER_TYPE_ID IN ('W04', 'W01', 'W02')

	UNION
	SELECT PROVIDER_CATEGORY_TYPE_ID, PROVIDER_TYPE_ID, 'Substitute W9', 'TypeOfEntity',0 ,0 , '2016-07-20 00:00:00.000' , '5D0689A8-D885-4211-B9FD-56757474AB4D', 
	'Provider Data Entry', 1, APPLICATION_TYPE_ID
	FROM PROVIDER_TYPE WHERE  MMIS_PROVIDER_TYPE_ID NOT IN ('I00')
	UNION
	SELECT PROVIDER_CATEGORY_TYPE_ID, PROVIDER_TYPE_ID, 'Substitute W9', 'TypeOfEntity',1 ,1 , '2016-07-20 00:00:00.000' , '5D0689A8-D885-4211-B9FD-56757474AB4D', 
	'Provider Review', 1, APPLICATION_TYPE_ID
	FROM PROVIDER_TYPE --WHERE  MMIS_PROVIDER_TYPE_ID IN ('W04', 'W01', 'W02')
	UNION
	SELECT PROVIDER_CATEGORY_TYPE_ID, PROVIDER_TYPE_ID, 'Substitute W9', 'TypeOfEntity',1 ,1 , '2016-07-20 00:00:00.000' , '5D0689A8-D885-4211-B9FD-56757474AB4D', 
	'Provider Data Entry', 1, APPLICATION_TYPE_ID
	FROM PROVIDER_TYPE WHERE  MMIS_PROVIDER_TYPE_ID IN ('I00')

	--I00
	IF EXISTS (SELECT REG_PAGE_SETTING_ID FROM REG_PAGE_SETTING WHERE REG_PAGE_NAME = 'Substitute W9' AND REG_PAGE_SECTION = '')
	BEGIN

	UPDATE REG_PAGE_SETTING SET REG_PAGE_NAME = 'Substitute W9 Form' WHERE REG_PAGE_NAME = 'Substitute W9' AND REG_PAGE_SECTION = ''

	END
	IF EXISTS (SELECT REG_PAGE_SETTING_ID FROM REG_PAGE_SETTING WHERE ENTITY_TYPE_ID = 3 AND PROVIDER_TYPE_ID = 151 AND REG_PAGE_NAME = 'Substitute W9' 
					AND REG_PAGE_SECTION = 'TaxClassification' AND IS_VISIBLE = 1 AND IS_EDITABLE = 1)
	BEGIN
		DELETE FROM REG_PAGE_SETTING 
		WHERE ENTITY_TYPE_ID = 3 AND PROVIDER_TYPE_ID = 151 AND REG_PAGE_NAME = 'Substitute W9' 
					AND REG_PAGE_SECTION = 'TaxClassification' AND IS_VISIBLE = 1 AND IS_EDITABLE = 1
	END

	IF EXISTS (SELECT REG_PAGE_SETTING_ID FROM REG_PAGE_SETTING WHERE ENTITY_TYPE_ID = 3 AND PROVIDER_TYPE_ID = 152 AND REG_PAGE_NAME = 'Substitute W9' 
					AND REG_PAGE_SECTION = 'TaxClassification' AND IS_VISIBLE = 1 AND IS_EDITABLE = 1)
	BEGIN
		DELETE FROM REG_PAGE_SETTING 
		WHERE ENTITY_TYPE_ID = 3 AND PROVIDER_TYPE_ID = 152 AND REG_PAGE_NAME = 'Substitute W9' 
					AND REG_PAGE_SECTION = 'TaxClassification' AND IS_VISIBLE = 1 AND IS_EDITABLE = 1
	END

	IF EXISTS (SELECT REG_PAGE_SETTING_ID FROM REG_PAGE_SETTING WHERE ENTITY_TYPE_ID = 3 AND PROVIDER_TYPE_ID = 153 AND REG_PAGE_NAME = 'Substitute W9' 
					AND REG_PAGE_SECTION = 'TaxClassification' AND IS_VISIBLE = 1 AND IS_EDITABLE = 1)
	BEGIN
		DELETE FROM REG_PAGE_SETTING 
		WHERE ENTITY_TYPE_ID = 3 AND PROVIDER_TYPE_ID = 153 AND REG_PAGE_NAME = 'Substitute W9' 
					AND REG_PAGE_SECTION = 'TaxClassification' AND IS_VISIBLE = 1 AND IS_EDITABLE = 1
	END


	-- Some more from Diwakar
	SELECT 1, 0, 'Group And Facility Affiliation', '',1 ,1 , '2016-07-20 00:00:00.000' , '5D0689A8-D885-4211-B9FD-56757474AB4D', 
	NULL, 1, NULL
	UNION
	SELECT 0, 0, 'Agreements', 'USCitizenship',0 ,0 , '2016-07-20 00:00:00.000' , '5D0689A8-D885-4211-B9FD-56757474AB4D', 
	NULL, 1, NULL



		
	UPDATE REG_PAGE_SETTING 
	SET IS_VISIBLE = 1, IS_EDITABLE = 1 
	WHERE PROVIDER_TYPE_ID IN (SELECT PROVIDER_TYPE_ID from PROVIDER_TYPE WHERE MMIS_PROVIDER_TYPE_ID = 'K01' and PROVIDER_CATEGORY_TYPE_ID = 2 and APPLICATION_TYPE_ID = 1)
	AND REG_PAGE_SECTION = 'CategoryOfService' 

	UPDATE REG_PAGE_SETTING 
	SET IS_VISIBLE = 0, IS_EDITABLE = 0 
	WHERE PROVIDER_TYPE_ID IN (SELECT PROVIDER_TYPE_ID from PROVIDER_TYPE WHERE MMIS_PROVIDER_TYPE_ID = 'X04' and PROVIDER_CATEGORY_TYPE_ID = 3 and APPLICATION_TYPE_ID = 1)
	AND REG_PAGE_SECTION = 'BehaviouralHealthInformation' 

	UPDATE [dbo].[REG_PAGE_SETTING]
	SET [IS_VISIBLE] =0,  [IS_EDITABLE] =0
	WHERE [APPLICATION_TYPE_ID] = 5 AND REG_PAGE_NAME = 'Agreements' AND Is_VISIBLE = 1 AND [REG_PAGE_SECTION] = 'AdditionalQuestions'

	/* Ambulance, Air Transport */
	SET @MMIS_PROVIDER_TYPE_ID = 'J02'
	IF EXISTS (SELECT REG_PAGE_SETTING_ID FROM REG_PAGE_SETTING 
				WHERE ENTITY_TYPE_ID=3 AND PROVIDER_TYPE_ID IN (SELECT PROVIDER_TYPE_ID FROM PROVIDER_TYPE WHERE MMIS_PROVIDER_TYPE_ID = @MMIS_PROVIDER_TYPE_ID) 
				AND REG_PAGE_NAME = 'Application Fee' AND IS_REQUIRED = 0 )
	UPDATE REG_PAGE_SETTING
	SET IS_REQUIRED = 1
		, IS_EDITABLE = 1
		, LAST_MODIFIED_DATE_TIME = @pin_run_reference_time
		, LAST_MODIFIED_USER = N'5D0689A8-D885-4211-B9FD-56757474AB4D'
	WHERE ENTITY_TYPE_ID=3 AND PROVIDER_TYPE_ID IN (SELECT PROVIDER_TYPE_ID FROM PROVIDER_TYPE WHERE MMIS_PROVIDER_TYPE_ID = @MMIS_PROVIDER_TYPE_ID) 
		AND REG_PAGE_NAME = 'Application Fee'

	/* J00	Ambulance, Private */
	SET @MMIS_PROVIDER_TYPE_ID = 'J00'
	IF EXISTS (SELECT REG_PAGE_SETTING_ID FROM REG_PAGE_SETTING 
				WHERE ENTITY_TYPE_ID=3 AND PROVIDER_TYPE_ID IN (SELECT PROVIDER_TYPE_ID FROM PROVIDER_TYPE WHERE MMIS_PROVIDER_TYPE_ID = @MMIS_PROVIDER_TYPE_ID) 
				AND REG_PAGE_NAME = 'Application Fee' AND IS_REQUIRED = 0 )
	UPDATE REG_PAGE_SETTING
	SET IS_REQUIRED = 1
		, IS_EDITABLE = 1
		, LAST_MODIFIED_DATE_TIME = @pin_run_reference_time
		, LAST_MODIFIED_USER = N'5D0689A8-D885-4211-B9FD-56757474AB4D'
	WHERE ENTITY_TYPE_ID=3 AND PROVIDER_TYPE_ID IN (SELECT PROVIDER_TYPE_ID FROM PROVIDER_TYPE WHERE MMIS_PROVIDER_TYPE_ID = @MMIS_PROVIDER_TYPE_ID) 
		AND REG_PAGE_NAME = 'Application Fee'

	/* J01	Ambulance, Public */
	SET @MMIS_PROVIDER_TYPE_ID = 'J01'
	IF EXISTS (SELECT REG_PAGE_SETTING_ID FROM REG_PAGE_SETTING 
				WHERE ENTITY_TYPE_ID=3 AND PROVIDER_TYPE_ID IN (SELECT PROVIDER_TYPE_ID FROM PROVIDER_TYPE WHERE MMIS_PROVIDER_TYPE_ID = @MMIS_PROVIDER_TYPE_ID) 
				AND REG_PAGE_NAME = 'Application Fee' AND IS_REQUIRED = 0 )
	UPDATE REG_PAGE_SETTING
	SET IS_REQUIRED = 1
		, IS_EDITABLE = 1
		, LAST_MODIFIED_DATE_TIME = @pin_run_reference_time
		, LAST_MODIFIED_USER = N'5D0689A8-D885-4211-B9FD-56757474AB4D'
	WHERE ENTITY_TYPE_ID=3 AND PROVIDER_TYPE_ID IN (SELECT PROVIDER_TYPE_ID FROM PROVIDER_TYPE WHERE MMIS_PROVIDER_TYPE_ID = @MMIS_PROVIDER_TYPE_ID) 
		AND REG_PAGE_NAME = 'Application Fee'

	-- V00	Ambulatory Surgical Centers 
	SET @MMIS_PROVIDER_TYPE_ID = 'V00'
	IF EXISTS (SELECT REG_PAGE_SETTING_ID FROM REG_PAGE_SETTING 
				WHERE ENTITY_TYPE_ID=3 AND PROVIDER_TYPE_ID IN (SELECT PROVIDER_TYPE_ID FROM PROVIDER_TYPE WHERE MMIS_PROVIDER_TYPE_ID = @MMIS_PROVIDER_TYPE_ID) 
				AND REG_PAGE_NAME = 'Application Fee' AND IS_REQUIRED = 0 )
	UPDATE REG_PAGE_SETTING
	SET IS_REQUIRED = 1
		, IS_EDITABLE = 1
		, LAST_MODIFIED_DATE_TIME = @pin_run_reference_time
		, LAST_MODIFIED_USER = N'5D0689A8-D885-4211-B9FD-56757474AB4D'
	WHERE ENTITY_TYPE_ID=3 AND PROVIDER_TYPE_ID IN (SELECT PROVIDER_TYPE_ID FROM PROVIDER_TYPE WHERE MMIS_PROVIDER_TYPE_ID = @MMIS_PROVIDER_TYPE_ID) 
		AND REG_PAGE_NAME = 'Application Fee'

	--X05	Clinic, Fed Qualified Health
	SET @MMIS_PROVIDER_TYPE_ID = 'X05'
	IF EXISTS (SELECT REG_PAGE_SETTING_ID FROM REG_PAGE_SETTING 
				WHERE ENTITY_TYPE_ID=3 AND PROVIDER_TYPE_ID IN (SELECT PROVIDER_TYPE_ID FROM PROVIDER_TYPE WHERE MMIS_PROVIDER_TYPE_ID = @MMIS_PROVIDER_TYPE_ID) 
				AND REG_PAGE_NAME = 'Application Fee' AND IS_REQUIRED = 0 )
	UPDATE REG_PAGE_SETTING
	SET IS_REQUIRED = 1
		, IS_EDITABLE = 1
		, LAST_MODIFIED_DATE_TIME = @pin_run_reference_time
		, LAST_MODIFIED_USER = N'5D0689A8-D885-4211-B9FD-56757474AB4D'
	WHERE ENTITY_TYPE_ID=3 AND PROVIDER_TYPE_ID IN (SELECT PROVIDER_TYPE_ID FROM PROVIDER_TYPE WHERE MMIS_PROVIDER_TYPE_ID = @MMIS_PROVIDER_TYPE_ID) 
		AND REG_PAGE_NAME = 'Application Fee'

	--I00	Durable Medical Equipment
	SET @MMIS_PROVIDER_TYPE_ID = 'I00'
	IF EXISTS (SELECT REG_PAGE_SETTING_ID FROM REG_PAGE_SETTING 
				WHERE ENTITY_TYPE_ID=3 AND PROVIDER_TYPE_ID IN (SELECT PROVIDER_TYPE_ID FROM PROVIDER_TYPE WHERE MMIS_PROVIDER_TYPE_ID = @MMIS_PROVIDER_TYPE_ID) 
				AND REG_PAGE_NAME = 'Application Fee' AND IS_REQUIRED = 0 )
	UPDATE REG_PAGE_SETTING
	SET IS_REQUIRED = 1
		, IS_EDITABLE = 1
		, LAST_MODIFIED_DATE_TIME = @pin_run_reference_time
		, LAST_MODIFIED_USER = N'5D0689A8-D885-4211-B9FD-56757474AB4D'
	WHERE ENTITY_TYPE_ID=3 AND PROVIDER_TYPE_ID IN (SELECT PROVIDER_TYPE_ID FROM PROVIDER_TYPE WHERE MMIS_PROVIDER_TYPE_ID = @MMIS_PROVIDER_TYPE_ID) 
		AND REG_PAGE_NAME = 'Application Fee'

	--Q01	Hemodialysis, Freestanding
	SET @MMIS_PROVIDER_TYPE_ID = 'Q01'
	IF EXISTS (SELECT REG_PAGE_SETTING_ID FROM REG_PAGE_SETTING 
				WHERE ENTITY_TYPE_ID=3 AND PROVIDER_TYPE_ID IN (SELECT PROVIDER_TYPE_ID FROM PROVIDER_TYPE WHERE MMIS_PROVIDER_TYPE_ID = @MMIS_PROVIDER_TYPE_ID) 
				AND REG_PAGE_NAME = 'Application Fee' AND IS_REQUIRED = 0 )
	UPDATE REG_PAGE_SETTING
	SET IS_REQUIRED = 1
		, IS_EDITABLE = 1
		, LAST_MODIFIED_DATE_TIME = @pin_run_reference_time
		, LAST_MODIFIED_USER = N'5D0689A8-D885-4211-B9FD-56757474AB4D'
	WHERE ENTITY_TYPE_ID=3 AND PROVIDER_TYPE_ID IN (SELECT PROVIDER_TYPE_ID FROM PROVIDER_TYPE WHERE MMIS_PROVIDER_TYPE_ID = @MMIS_PROVIDER_TYPE_ID) 
		AND REG_PAGE_NAME = 'Application Fee'

	--L00	Home Health Agency
	SET @MMIS_PROVIDER_TYPE_ID = 'L00'
	IF EXISTS (SELECT REG_PAGE_SETTING_ID FROM REG_PAGE_SETTING 
				WHERE ENTITY_TYPE_ID=3 AND PROVIDER_TYPE_ID IN (SELECT PROVIDER_TYPE_ID FROM PROVIDER_TYPE WHERE MMIS_PROVIDER_TYPE_ID = @MMIS_PROVIDER_TYPE_ID) 
				AND REG_PAGE_NAME = 'Application Fee' AND IS_REQUIRED = 0 )
	UPDATE REG_PAGE_SETTING
	SET IS_REQUIRED = 1
		, IS_EDITABLE = 1
		, LAST_MODIFIED_DATE_TIME = @pin_run_reference_time
		, LAST_MODIFIED_USER = N'5D0689A8-D885-4211-B9FD-56757474AB4D'
	WHERE ENTITY_TYPE_ID=3 AND PROVIDER_TYPE_ID IN (SELECT PROVIDER_TYPE_ID FROM PROVIDER_TYPE WHERE MMIS_PROVIDER_TYPE_ID = @MMIS_PROVIDER_TYPE_ID) 
		AND REG_PAGE_NAME = 'Application Fee'

	--L01	Hospice
	SET @MMIS_PROVIDER_TYPE_ID = 'L01'
	IF EXISTS (SELECT REG_PAGE_SETTING_ID FROM REG_PAGE_SETTING 
				WHERE ENTITY_TYPE_ID=3 AND PROVIDER_TYPE_ID IN (SELECT PROVIDER_TYPE_ID FROM PROVIDER_TYPE WHERE MMIS_PROVIDER_TYPE_ID = @MMIS_PROVIDER_TYPE_ID) 
				AND REG_PAGE_NAME = 'Application Fee' AND IS_REQUIRED = 0 )
	UPDATE REG_PAGE_SETTING
	SET IS_REQUIRED = 1
		, IS_EDITABLE = 1
		, LAST_MODIFIED_DATE_TIME = @pin_run_reference_time
		, LAST_MODIFIED_USER = N'5D0689A8-D885-4211-B9FD-56757474AB4D'
	WHERE ENTITY_TYPE_ID=3 AND PROVIDER_TYPE_ID IN (SELECT PROVIDER_TYPE_ID FROM PROVIDER_TYPE WHERE MMIS_PROVIDER_TYPE_ID = @MMIS_PROVIDER_TYPE_ID) 
		AND REG_PAGE_NAME = 'Application Fee'

	--D04	Hospital, Emergency Access
	SET @MMIS_PROVIDER_TYPE_ID = 'D04'
	IF EXISTS (SELECT REG_PAGE_SETTING_ID FROM REG_PAGE_SETTING 
				WHERE ENTITY_TYPE_ID=3 AND PROVIDER_TYPE_ID IN (SELECT PROVIDER_TYPE_ID FROM PROVIDER_TYPE WHERE MMIS_PROVIDER_TYPE_ID = @MMIS_PROVIDER_TYPE_ID) 
				AND REG_PAGE_NAME = 'Application Fee' AND IS_REQUIRED = 0 )
	UPDATE REG_PAGE_SETTING
	SET IS_REQUIRED = 1
		, IS_EDITABLE = 1
