	-- Remove duplicates
	WITH keepThese AS (
		SELECT min(REG_PAGE_SETTING_ID) as REG_PAGE_SETTING_ID, ENTITY_TYPE_ID, PROVIDER_TYPE_ID, REG_PAGE_NAME, REG_PAGE_SECTION,
		 IS_VISIBLE, IS_EDITABLE, TASK_NAME, IS_REQUIRED, APPLICATION_TYPE_ID
		FROM dbo.REG_PAGE_SETTING 
		GROUP BY ENTITY_TYPE_ID, PROVIDER_TYPE_ID, REG_PAGE_NAME, REG_PAGE_SECTION, IS_VISIBLE, IS_EDITABLE, TASK_NAME,
		 IS_REQUIRED, APPLICATION_TYPE_ID
		HAVING count(*) = 1
		UNION
		SELECT min(REG_PAGE_SETTING_ID) as REG_PAGE_SETTING_ID, ENTITY_TYPE_ID, PROVIDER_TYPE_ID, REG_PAGE_NAME, REG_PAGE_SECTION,
		 IS_VISIBLE, IS_EDITABLE, TASK_NAME, IS_REQUIRED, APPLICATION_TYPE_ID
		FROM dbo.REG_PAGE_SETTING 
		GROUP BY ENTITY_TYPE_ID, PROVIDER_TYPE_ID, REG_PAGE_NAME, REG_PAGE_SECTION, IS_VISIBLE, IS_EDITABLE, TASK_NAME,
		 IS_REQUIRED, APPLICATION_TYPE_ID
		HAVING count(*) > 1
		)
	DELETE [dbo].[REG_PAGE_SETTING]
	FROM [dbo].[REG_PAGE_SETTING] a
	LEFT JOIN keepThese b ON a.REG_PAGE_SETTING_ID = b.REG_PAGE_SETTING_ID
	WHERE b.REG_PAGE_SETTING_ID is null;  


